// --- Per-profile tool selection (include / exclude) ----------------------------
//
// Lets a profile register only a subset of the canonical native tools without
// forking this extension. Resolution order (first wins per field):
//   1. env: PI_NATIVE_TOOL_INCLUDE / PI_NATIVE_TOOL_EXCLUDE (comma-separated)
//   2. settings.json: extensions.native-tool-overrides.{include,exclude}
//   3. defaults (register everything)
//
// `include` is an allowlist (only these register). `exclude` is a denylist
// (everything except these). If both resolve, include is applied first, then
// exclude removes from it. Names match the capability case-insensitively
// (e.g. "Agent", "agent" both exclude the Agent alias).
//
// CACHE CRITICAL: this is read once at load and gates which schemas enter the
// stable first-turn tools[] set. It must be deterministic per process; never
// derive it from per-turn state.
interface NativeToolSelection {
  include: Set<string> | null;
  exclude: Set<string>;
}

function parseNameList(raw: unknown): string[] {
  if (typeof raw === "string") return raw.split(",").map((s) => s.trim()).filter(Boolean);
  if (Array.isArray(raw)) return raw.filter((s): s is string => typeof s === "string").map((s) => s.trim()).filter(Boolean);
  return [];
}

function loadSelection(): NativeToolSelection {
  let includeNames = parseNameList(process.env.PI_NATIVE_TOOL_INCLUDE);
  let excludeNames = parseNameList(process.env.PI_NATIVE_TOOL_EXCLUDE);

  if (includeNames.length === 0 || excludeNames.length === 0) {
    const path = join(process.env.PI_CODING_AGENT_DIR || join(homedir(), ".pi", "agent"), "settings.json");
    try {
      const raw = readFileSync(path, "utf8");
      const parsed = JSON.parse(raw) as {
        extensions?: { "native-tool-overrides"?: { include?: unknown; exclude?: unknown } };
      };
      const cfg = parsed.extensions?.["native-tool-overrides"];
      if (includeNames.length === 0) includeNames = parseNameList(cfg?.include);
      if (excludeNames.length === 0) excludeNames = parseNameList(cfg?.exclude);
    } catch {
      // No settings.json / unreadable — fall back to env + defaults.
    }
  }

  const norm = (s: string) => s.toLowerCase();
  return {
    include: includeNames.length > 0 ? new Set(includeNames.map(norm)) : null,
    exclude: new Set(excludeNames.map(norm)),
  };
}

function makeIsEnabled(selection: NativeToolSelection): (name: string) => boolean {
  return (name: string) => {
    const key = name.toLowerCase();
    if (selection.include && !selection.include.has(key)) return false;
    if (selection.exclude.has(key)) return false;
    return true;
  };
}

// --- Edit-tool argument repair (fork-local, kept out of pi core) ----------------
//
// Some models cram extra replacements onto one Edit call as numbered siblings
// (oldText2/newText2, oldText3/newText3, ...) instead of using the edits[] array.
// The core Edit schema is additionalProperties:false, so those calls hard-reject.
// Upstream already folds a single top-level oldText/newText pair; we extend that
// to numbered siblings here rather than patching core, so pi-mono-fork stays at
// upstream shape. We normalize the numbered pairs into edits[], then delegate to
// the upstream prepareArguments for its JSON-string + single-pair handling.
type EditReplacement = { oldText: string; newText: string };

function foldNumberedEditPairs(input: unknown): unknown {
  if (!input || typeof input !== "object") return input;
  const args = input as Record<string, unknown>;
  const pairs: EditReplacement[] = [];
  const consumed = new Set<string>();
  if (typeof args.oldText === "string" && typeof args.newText === "string") {
    pairs.push({ oldText: args.oldText, newText: args.newText });
    consumed.add("oldText").add("newText");
  }
  for (let n = 2; ; n++) {
    const oldKey = `oldText${n}`;
    const newKey = `newText${n}`;
    if (typeof args[oldKey] !== "string" || typeof args[newKey] !== "string") break;
    pairs.push({ oldText: args[oldKey] as string, newText: args[newKey] as string });
    consumed.add(oldKey).add(newKey);
  }
  if (pairs.length === 0) return input;
  const existing = Array.isArray(args.edits) ? (args.edits as EditReplacement[]) : [];
  const rest = Object.fromEntries(Object.entries(args).filter(([key]) => !consumed.has(key)));
  return { ...rest, edits: [...existing, ...pairs] };
}

function withNumberedEditRepair<T extends { prepareArguments?: (input: unknown) => unknown }>(definition: T): T {
  const upstreamPrepare = definition.prepareArguments;
  return {
    ...definition,
    prepareArguments: (input: unknown) => {
      const folded = foldNumberedEditPairs(input);
      return upstreamPrepare ? upstreamPrepare(folded) : folded;
    },
  };
}

