// to a *different* directory is left untouched (core already allows that). Done in the
// extension wrapper's prepareArguments so pi-mono-fork core stays at upstream shape.
const REDUNDANT_CD_PREFIX = /^(\s*cd\s+("[^"]+"|'[^']+'|(?:\\\S|\S)+)\s*(?:&&|;)\s*)(?=\S)/s;
function unquoteShellPath(value: string): string {
  if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
    return value.slice(1, -1);
  }
  return value.replace(/\\ /g, " ");
}
export function stripRedundantCd(command: string, cwd: string): string {
  const match = REDUNDANT_CD_PREFIX.exec(command);
  if (!match) return command;
  let target = unquoteShellPath(match[2]!);
  if (target === "~" || target.startsWith("~/")) target = join(homedir(), target.slice(2));
  if (resolve(cwd, target) !== resolve(cwd)) return command;
  return command.slice(match[1]!.length);
}

